CREATE TABLE IF NOT EXISTS `dpn_medical_insurance_policies` (`id` bigint unsigned NOT NULL AUTO_INCREMENT,`citizenid` varchar(64) NOT NULL,`plan_id` varchar(32) NOT NULL,`premium` int NOT NULL,`status` varchar(32) NOT NULL,`created_at` timestamp NOT NULL DEFAULT current_timestamp(),PRIMARY KEY (`id`),KEY `idx_policy_cid` (`citizenid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `dpn_medical_insurance_claims` (`id` bigint unsigned NOT NULL AUTO_INCREMENT,`citizenid` varchar(64) NOT NULL,`policy_id` bigint NULL,`invoice_id` bigint NULL,`category` varchar(64) NULL,`amount` int NOT NULL,`covered_amount` int NOT NULL,`patient_amount` int NOT NULL,`status` varchar(32) NOT NULL,`created_at` timestamp NOT NULL DEFAULT current_timestamp(),PRIMARY KEY (`id`),KEY `idx_claim_cid` (`citizenid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
